def compute(vars):
    value = vars["v1"] - vars["v2"]
    return {
        "value": value,
        "trace": {
            "fair_value_2010": vars["v1"],
            "fair_value_2009": vars["v2"],
            "change": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
